s.c:
.flip { perspective: 600px; }
.inner {
  position: relative;
  transform-style: preserve-3d;
  transition: transform .6s;
}
.flip:hover .inner { transform: rotateY(180deg); }
.front, .back { position: absolute; inset: 0; backface-visibility: hidden; }
.back { transform: rotateY(180deg); }

.loader span {
  display: inline-block;
  width: 8px;
  background: #09f;
  animation: bounce 1s infinite;
}
.loader span:nth-child(2) { animation-delay: .15s; }
.loader span:nth-child(3) { animation-delay: .3s; }

ex.sol:
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  animation: pulse 1s infinite;
}
.dot:nth-child(2) { animation-delay: .2s; }
@keyframes pulse { 50% { transform: scale(1.5); } }

@keyframes up {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: none; opacity: 1; }
}

